INSERT INTO battle_questions
  (src_key, level, category, question_text, answer, wrong1, wrong2, wrong3, wrong4, wrong5, explanation, needs_calc, is_active)
VALUES
('chikyu_lv4_001', 4, 'chikyu', '新月の日、月は正午に南中する。月は1日に約50分ずつおそく南中するとき、月齢3.5の月が南中するのは約何時？', '約15時', '約12時30分', '約9時', '約18時', '約21時', '約0時', '50分×3.5日＝175分（約3時間）おそくなるので、正午の約3時間後の約15時（午後3時）。', 1, 1),
('chikyu_lv4_002', 4, 'chikyu', '満月は真夜中0時に南中する。月は1日に約50分ずつおそく南中するとき、満月の3日後の月が南中するのは？', '午前2時30分ごろ', '午前0時50分ごろ', '午前1時ごろ', '午前3時30分ごろ', '午後9時30分ごろ', '午前5時ごろ', '50分×3日＝150分（2時間30分）おそくなるので、午前0時の2時間30分後の午前2時30分ごろ。', 1, 1),
('chikyu_lv4_003', 4, 'chikyu', '下弦の月が南中するのは、およそいつ？', '午前6時ごろ', '正午ごろ', '午後6時ごろ', '午前0時ごろ', '午前3時ごろ', '午後3時ごろ', '下弦の月は真夜中ごろにのぼり、明け方の午前6時ごろに南中し、正午ごろにしずむ。', 0, 1),
('chikyu_lv4_004', 4, 'chikyu', '太陽をほぼかくす「金環日食」が起こるのは、どんなとき？', '月が遠くて太陽よりやや小さく見えるとき', '月が近くて太陽より大きく見えるとき', '太陽が地球から遠くにあるとき', '地球のかげに月が入るとき', '月が満月のとき', '太陽の黒点が多いとき', '月の見かけの大きさが太陽よりわずかに小さいと、太陽が輪のように残る。新月のころに起こる。', 0, 1),
('chikyu_lv4_005', 4, 'chikyu', '皆既月食のとき、月が暗い赤銅色に見える理由は？', '地球の大気で曲がった赤い光が届くから', '月が自分で赤く光るから', '太陽の光が月に直接当たるから', '地球のかげが赤いから', '月の表面が高温になるから', '月の鉄さびが光を出すから', '地球の大気を通った光のうち、赤い光が屈折して地球のかげの中の月に届くので、赤黒く見える。', 0, 1),
('chikyu_lv4_006', 4, 'chikyu', '北緯35度の地点で、春分の日の太陽の南中高度は何度？', '55度', '35度', '65度', '58.4度', '78.4度', '31.6度', '春分・秋分の南中高度は「90度－緯度」。90－35＝55度。', 1, 1),
('chikyu_lv4_007', 4, 'chikyu', '地軸のかたむきを23.4度として、北緯35度の地点で夏至の日の太陽の南中高度は何度？', '78.4度', '55度', '58.4度', '31.6度', '66.6度', '90度', '夏至の南中高度は「90度－緯度＋23.4度」。90－35＋23.4＝78.4度。', 1, 1),
('chikyu_lv4_008', 4, 'chikyu', '地軸のかたむきを23.4度として、北緯40度の地点で冬至の日の太陽の南中高度は何度？', '26.6度', '73.4度', '50度', '63.4度', '16.6度', '33.4度', '冬至の南中高度は「90度－緯度－23.4度」。90－40－23.4＝26.6度。', 1, 1),
('chikyu_lv4_009', 4, 'chikyu', '春分の日の太陽の南中高度が60度だった地点の緯度は、北緯何度？', '北緯30度', '北緯60度', '北緯45度', '北緯36.6度', '北緯23.4度', '北緯20度', '春分の南中高度＝90度－緯度なので、緯度＝90－60＝30度。', 1, 1),
('chikyu_lv4_010', 4, 'chikyu', '夏至のころ、北極圏（北緯約66.6度より北）で見られる、1日中太陽がしずまない現象を何という？', '白夜', '極夜', 'オーロラ', '日周運動', '皆既日食', '蜃気楼', '地軸がかたむいているため、夏至のころ北極圏では太陽がしずまない。冬は逆に1日中のぼらない（極夜）。', 0, 1),
('chikyu_lv4_011', 4, 'chikyu', '同じ星が真南に見える時刻は1日に約4分ずつ早くなる。今夜8時に真南に見えた星は、30日後は何時ごろ真南に見える？', '午後6時ごろ', '午後10時ごろ', '午後7時ごろ', '午後8時ごろ', '午前6時ごろ', '午後4時ごろ', '4分×30日＝120分（2時間）早くなるので、午後8時の2時間前の午後6時ごろ。', 1, 1),
('chikyu_lv4_012', 4, 'chikyu', '金星が真夜中に見えないのはなぜ？', '地球より内側を回っているから', '地球のかげに入ってしまうから', '太陽の光を反射しないから', '月にかくれてしまうから', '1日の半分は自転で消えるから', '地球より外側を回っているから', '金星は地球より内側の軌道を回るので、明け方の東の空か夕方の西の空にしか見えない。', 0, 1),
('chikyu_lv4_013', 4, 'chikyu', '次の惑星のうち、木星型惑星（大きくて密度が小さい）はどれ？', '天王星', '水星', '金星', '地球', '火星', '小わく星', '木星・土星・天王星・海王星が木星型。水星・金星・地球・火星は小さくて岩石でできた地球型。', 0, 1),
('chikyu_lv4_014', 4, 'chikyu', '月の満ち欠けが1回くり返される周期（新月から次の新月まで）は約何日？', '約29.5日', '約7日', '約14日', '約21日', '約45日', '約60日', '新月から次の新月まで約29.5日。上弦・満月・下弦と、約7日ごとに形が変わる。', 0, 1),
('chikyu_lv4_015', 4, 'chikyu', '潮の満ち引きの差がいちばん大きい「大潮」になるのは、いつごろ？', '新月と満月のころ', '上弦の月と下弦の月のころ', '三日月のころ', '月が南中するころ', '夏至と冬至の日', '月が地平線にあるころ', '月と太陽と地球が一直線にならぶ新月・満月のころは、引力が重なって潮の差が大きくなる。', 0, 1),
('chikyu_lv4_016', 4, 'chikyu', '日本が夏至のころ、南半球のオーストラリア南部の季節はどれ？', '冬', '春', '夏', '秋', '梅雨', '一年中同じ', '南半球は北半球と季節が逆。日本が夏のとき冬、日本が冬のとき夏になる。', 0, 1),
('chikyu_lv4_017', 4, 'chikyu', '地球が太陽のまわりを公転して、1日に進む角度は約何度？', '約1度', '約0.5度', '約2度', '約15度', '約30度', '約360度', '1年（約365日）で360度回るので、1日に約1度進む。1日で約15度回って見えるのは自転のほう。', 0, 1),
('chikyu_lv4_018', 4, 'chikyu', '春の大三角をつくる星のうち、しし座の星はどれ？', 'デネボラ', 'アルタイル', 'プロキオン', 'ベテルギウス', 'カペラ', 'フォーマルハウト', '春の大三角は、うしかい座のアークトゥルス・おとめ座のスピカ・しし座のデネボラ。', 0, 1),
('chikyu_lv4_019', 4, 'chikyu', '冬の大三角をつくる星のうち、こいぬ座の星はどれ？', 'プロキオン', 'アルデバラン', 'リゲル', 'カペラ', 'ポルックス', 'レグルス', '冬の大三角は、おおいぬ座のシリウス・こいぬ座のプロキオン・オリオン座のベテルギウス。', 0, 1),
('chikyu_lv4_020', 4, 'chikyu', '太陽の黒点を毎日観察すると、黒点は太陽の表面をどの向きに動いていく？', '東から西へ', '西から東へ', '北から南へ', '南から北へ', '動かない', '日によって向きが変わる', '太陽が自転しているため、黒点は東から西へ動いていく。地球から見ると、約27日で太陽を1周する。', 0, 1),
('chikyu_lv4_021', 4, 'chikyu', '皆既日食のとき、太陽のまわりに真珠色にひろがって見える、高温のうすいガスの層は？', 'コロナ', 'プロミネンス', '黒点', '彩層', 'オーロラ', 'ダイヤモンドリング', 'コロナは太陽の外側にひろがる非常に高温のガス。ふだんは太陽がまぶしくて見えない。', 0, 1),
('chikyu_lv4_022', 4, 'chikyu', '日本の標準時は東経135度の時刻。日本が正午のとき、東経0度（イギリスの経度）は何時？（サマータイムは考えない）', '午前3時', '午前9時', '午前6時', '午後3時', '午後9時', '午前0時', '経度15度で1時間の時差。135÷15＝9時間おそいので、正午の9時間前の午前3時。', 1, 1),
('chikyu_lv4_023', 4, 'chikyu', '太陽が真南に来る時刻は、東経135度の地点の正午ごろ。同じ緯度で東経150度の地点では、太陽が真南に来るのはいつ？', '正午より1時間早い', '正午より1時間おそい', '正午より15分早い', '正午より15分おそい', '正午より2時間早い', '正午と同じ', '東にいくほど太陽が早く南中する。経度15度で1時間なので、150－135＝15度で1時間早い。', 1, 1),
('chikyu_lv4_024', 4, 'chikyu', 'すい星の尾は、太陽の近くにあるとき、いつもどちらの向きにのびる？', '太陽と反対の向き', '太陽の向き', '進む向き', '進む向きと反対', '地球の向き', '北の向き', '尾は太陽の光や太陽風でふき流されるので、進む向きにかかわらず太陽と反対向きにのびる。', 0, 1),
('chikyu_lv4_025', 4, 'chikyu', '日本で、南中高度が高い空を通るのは、夏の満月と冬の満月のどちら？', '冬の満月', '夏の満月', 'どちらも同じ', '年によって入れかわる', 'どちらも真上を通る', 'どちらも低い空を通る', '満月は太陽の反対側にある。夏は太陽が高く満月は低く、冬は太陽が低く満月が高く見える。', 0, 1),
('chikyu_lv4_026', 4, 'chikyu', '気温20℃の空気1m³に水蒸気が6.92gふくまれている。20℃の飽和水蒸気量は17.3g/m³。湿度は何％？', '40％', '25％', '30％', '60％', '80％', '250％', '湿度＝水蒸気量÷飽和水蒸気量×100＝6.92÷17.3×100＝40％。', 1, 1),
('chikyu_lv4_027', 4, 'chikyu', '気温25℃の空気1m³に水蒸気が13.86gふくまれている。25℃の飽和水蒸気量は23.1g/m³。湿度は何％？', '60％', '40％', '50％', '70％', '80％', '167％', '13.86÷23.1×100＝60％。', 1, 1),
('chikyu_lv4_028', 4, 'chikyu', '気温30℃の空気1m³に水蒸気が17.3gある。飽和水蒸気量は15℃で12.8g、20℃で17.3g、25℃で23.1g、30℃で30.4g（g/m³）。この空気の露点は？', '20℃', '15℃', '25℃', '30℃', '10℃', '17.3℃', '空気が冷えて、ふくむ水蒸気量が飽和水蒸気量とちょうど等しくなる温度が露点。17.3gは20℃の飽和水蒸気量。', 1, 1),
('chikyu_lv4_029', 4, 'chikyu', '気温30℃・湿度50％の空気1m³を15℃まで冷やした。30℃の飽和水蒸気量は30.4g/m³、15℃は12.8g/m³。1m³あたり何gの水滴ができる？', '2.4g', '12.8g', '15.2g', '17.6g', '1.2g', '0.5g', '30℃の水蒸気量は30.4×0.5＝15.2g。15℃にふくめるのは12.8gまでなので、15.2－12.8＝2.4gが水滴になる。', 1, 1),
('chikyu_lv4_030', 4, 'chikyu', '気温20℃、湿度40％の部屋（50m³）がある。湿度を70％にするには水蒸気を約何gふやせばよいか。20℃の飽和水蒸気量は17.3g/m³。', '約260g', '約346g', '約520g', '約865g', '約86g', '約173g', '1m³あたり17.3×(0.7－0.4)＝5.19g。部屋全体では5.19×50＝259.5gで約260g。', 1, 1),
('chikyu_lv4_031', 4, 'chikyu', '乾湿計で、湿球の示度が乾球よりも低くなるのはなぜ？', 'ガーゼの水が蒸発して熱をうばうから', 'ガーゼの水が熱を出すから', '湿球のほうが日光に当たるから', '湿球の中の液がちがうから', '水が冷たいから', '風が湿球にだけ当たるから', '水が蒸発するときに周りの熱をうばうので湿球は冷える。空気がかわいているほど蒸発しやすく、差が大きい。', 0, 1),
('chikyu_lv4_032', 4, 'chikyu', '寒冷前線が通りすぎたあと、風向きと気温はどう変わる？', '風は北寄りに変わり気温が下がる', '風は南寄りに変わり気温が下がる', '風は北寄りに変わり気温が上がる', '風は南寄りに変わり気温が上がる', '風向きは変わらず気温が下がる', '風向きは変わらず気温が上がる', '寒気が暖気の下にもぐりこむので、通過後は北寄りの風に変わり、気温が急に下がる。', 0, 1),
('chikyu_lv4_033', 4, 'chikyu', '温暖前線の近くで降る雨の特ちょうは？', '弱い雨が広いはんいで長く降る', '強い雨が狭いはんいで短時間降る', '雷をともなう強い雨が降る', '雨はほとんど降らない', 'ひょうが降りやすい', '雨のあとすぐに晴れる', '暖気がゆるやかにのし上がるので乱層雲ができ、広い地域にしとしと長く降る。強い雨は寒冷前線の特ちょう。', 0, 1),
('chikyu_lv4_034', 4, 'chikyu', '台風の進む向きの右側が、左側より風が強くなりやすいのはなぜ？', '台風の風に、台風が進む速さが加わるから', '台風の目が右にかたよっているから', '右側のほうが海水温が高いから', '地球の自転で右側だけ加速するから', '右側にだけ前線があるから', '左側は陸地があるから', '北半球の台風は反時計回りに風がふく。右側では台風の風の向きと進む向きが同じになり、風が強まる。', 0, 1),
('chikyu_lv4_035', 4, 'chikyu', '高気圧の中心付近では、空気はおもにどのように動いている？', '下降している', '上昇している', '中心にふきこんでいる', '動いていない', 'まっすぐ東へ進んでいる', '上下に何度もくり返し動く', '高気圧の中心では空気が下降し、雲ができにくいので晴れやすい。低気圧では上昇気流ができて雲が発生する。', 0, 1),
('chikyu_lv4_036', 4, 'chikyu', 'よく晴れた日の昼間、海岸ではどんな風がふくことが多い？', '海から陸へふく風', '陸から海へふく風', '山から谷へふく風', '海岸線にそってふく風', '風はほとんどふかない', '上空から地面へふく風', '昼は陸のほうが海よりあたたまりやすく、陸の上で上昇気流ができて、海から陸へ風がふく（海風）。', 0, 1),
('chikyu_lv4_037', 4, 'chikyu', '冬に日本海側の地方で雪が多く降る主な理由は？', '水蒸気を多くふくむ風が山にぶつかるから', '暖流のせいで雪がとけないから', '太平洋の湿った空気が流れこむから', '台風が冬に多く来るから', '日本海の水が冷たいから', '偏西風が止まるから', '大陸からの冷たい季節風が暖かい日本海から水蒸気をもらい、山脈にぶつかって雪雲になる。', 0, 1),
('chikyu_lv4_038', 4, 'chikyu', '冬の日本付近でよく見られる「西高東低」の気圧配置では、高気圧はどこにある？', '大陸（シベリア付近）', '太平洋', '日本海', 'オホーツク海', '赤道付近', '南極', '大陸の高気圧から太平洋の低気圧に向かって北西の季節風がふき、日本海側に雪を降らせる。', 0, 1),
('chikyu_lv4_039', 4, 'chikyu', '1気圧は水銀柱76cmの重さとつりあう。水銀は水の13.6倍重いので、水の柱で1気圧をはかると、高さは約何mになる？', '約10m', '約0.76m', '約1m', '約5m', '約76m', '約100m', '同じ重さの柱の高さは重さに反比例する。76cm×13.6＝約10.3mなので、約10m。', 1, 1),
('chikyu_lv4_040', 4, 'chikyu', '空気のかたまりが上昇すると雲ができやすい。その理由として正しいものは？', '気圧が低く、空気が膨張して冷えるから', '気圧が高く、空気が縮んで冷えるから', '上空は日光が強く、水蒸気がふえるから', '地面から水がふき出すから', '上空の風で水滴がくっつくから', '空気中の酸素が水に変わるから', '上昇した空気は膨張して冷え、露点以下になると水蒸気が水滴や氷の粒になって雲ができる。', 0, 1),
('chikyu_lv4_041', 4, 'chikyu', 'ある時代にだけ栄えて広い地域にすんでいた生き物の化石で、地層ができた時代を知る手がかりになるものを何という？', '示準化石', '示相化石', '生痕化石', '微化石', '生きた化石', '完全化石', '示準化石は地層の時代を決める化石。当時の環境を知る手がかりになるのは示相化石。', 0, 1),
('chikyu_lv4_042', 4, 'chikyu', '三葉虫の化石が見つかった地層は、どの時代にできたと考えられる？', '古生代', '中生代', '新生代', '先カンブリア時代', '第四紀', '白亜紀', '三葉虫は古生代に栄えた示準化石。アンモナイトは中生代、ナウマンゾウは新生代の示準化石。', 0, 1),
('chikyu_lv4_043', 4, 'chikyu', 'サンゴの化石が見つかった地層は、どんな環境でできたと考えられる？', 'あたたかくて浅い海', '冷たくて深い海', '川の上流', '湖や河口', '高い山の上', '砂ばくの中', '造礁サンゴは、あたたかくて浅いきれいな海にすむ。このように当時の環境がわかる化石を示相化石という。', 0, 1),
('chikyu_lv4_044', 4, 'chikyu', 'P波の速さを秒速6km、S波の速さを秒速4kmとする。初期微動継続時間が10秒だった地点は、震源から何kmはなれている？', '120km', '40km', '60km', '100km', '20km', '240km', '震源距離をdとすると d/4－d/6＝10 より d＝120km。初期微動継続時間は震源距離に比例する。', 1, 1),
('chikyu_lv4_045', 4, 'chikyu', 'P波が秒速7km、S波が秒速4kmの地しんで、震源から84kmの地点の初期微動継続時間は何秒？', '9秒', '3秒', '12秒', '21秒', '30秒', '42秒', 'P波は84÷7＝12秒、S波は84÷4＝21秒で届く。その差21－12＝9秒が初期微動継続時間。', 1, 1),
('chikyu_lv4_046', 4, 'chikyu', 'P波が秒速6km、S波が秒速4kmの地しんで、ある地点にP波が10時0分20秒、S波が10時0分30秒に届いた。地しんが発生した時刻は？', '10時0分00秒', '10時0分10秒', '10時0分20秒', '10時0分30秒', '9時59分50秒', '10時0分05秒', '継続時間10秒より震源距離は120km。P波が届くのに120÷6＝20秒かかるので、発生は20秒前の10時0分00秒。', 1, 1),
('chikyu_lv4_047', 4, 'chikyu', '地しんが起きたとき、先に届くゆれと、大きなゆれ（主要動）をおこす波の組み合わせは？', 'P波が先に届き、S波が主要動をおこす', 'S波が先に届き、P波が主要動をおこす', 'P波が先に届き、P波が主要動をおこす', 'S波が先に届き、S波が主要動をおこす', '同時に届き、P波が主要動をおこす', '同時に届き、S波が主要動をおこす', '速いP波が小さなゆれ（初期微動）を、おくれて届くS波が大きなゆれ（主要動）をおこす。', 0, 1),
('chikyu_lv4_048', 4, 'chikyu', 'マグマのねばりけが強い火山の、ふつうの形と溶岩の色はどれ？', '盛り上がった形で白っぽい', 'なだらかな形で白っぽい', '盛り上がった形で黒っぽい', 'なだらかな形で黒っぽい', '平らな台地になって白っぽい', 'へこんだ形で黒っぽい', 'ねばりけが強いと流れにくく、盛り上がった形（昭和新山など）で白っぽい。弱いとなだらかで黒っぽい（ハワイなど）。', 0, 1),
('chikyu_lv4_049', 4, 'chikyu', '川が運んだつぶが海に積もるとき、河口からいちばん遠い沖まで運ばれて積もるのはどれ？', 'どろ', 'れき', '砂', '大きな岩', '丸い石', '小石', '重くて大きいつぶほど河口近くに積もり、軽くて細かいどろは沖まで運ばれる。', 0, 1),
('chikyu_lv4_050', 4, 'chikyu', 'ある海底では、どろが1000年で1cmの割合で積もる。厚さ3mのどろの層ができるには、約何年かかる？', '約30万年', '約3000年', '約3万年', '約10万年', '約60万年', '約300万年', '3m＝300cm。1cmに1000年かかるので、300×1000＝30万年。', 1, 1),
('chikyu_lv4_051', 4, 'chikyu', '硝酸カリウムは、水100gに60℃で110g、20℃で32gまでとける。60℃の水100gに限度までとかした水よう液を20℃に冷やすと、何gの結晶が出る？', '78g', '32g', '110g', '142g', '210g', '88g', '60℃でとけていた110gのうち、20℃でとけていられるのは32g。110－32＝78gが結晶になる。', 1, 1),
('chikyu_lv4_052', 4, 'chikyu', '硝酸カリウムは、水100gに60℃で110g、20℃で32gまでとける。60℃の水200gに限度までとかした水よう液を20℃に冷やすと、何gの結晶が出る？', '156g', '78g', '64g', '220g', '110g', '300g', '水100gなら78g出る。水が200gなら2倍で、78×2＝156g。', 1, 1),
('chikyu_lv4_053', 4, 'chikyu', '20℃の水100gに食塩は36gまでとける。20℃の水150gには、食塩は最大何gまでとける？', '54g', '36g', '72g', '24g', '90g', '18g', '水の量に比例してとける。36×150÷100＝54g。', 1, 1),
('chikyu_lv4_054', 4, 'chikyu', '20℃の水100gに食塩は36gまでとける。20℃の食塩の飽和水よう液の濃さは、約何％？', '約26％', '36％', '約20％', '18％', '約64％', '約13％', '飽和水よう液は水100g＋食塩36g＝136g。濃さ＝36÷136×100＝約26％。水100gに対する36gの36％と混同しない。', 1, 1),
('chikyu_lv4_055', 4, 'chikyu', '10％の食塩水200gと5％の食塩水300gを混ぜると、何％の食塩水になる？', '7％', '7.5％', '15％', '5％', '8％', '6％', '食塩は200×0.10＋300×0.05＝20＋15＝35g。全体は500gなので、35÷500＝7％。平均の7.5％にはならない。', 1, 1),
('chikyu_lv4_056', 4, 'chikyu', '10％の食塩水200gから水を蒸発させて20％にするには、何gの水を蒸発させればよいか。', '100g', '50g', '20g', '10g', '150g', '80g', '食塩は200×0.1＝20gで変わらない。20％で20gなら全体は100gなので、200－100＝100g蒸発させる。', 1, 1),
('chikyu_lv4_057', 4, 'chikyu', '10％の食塩水400gに食塩を加えて20％にしたい。何gの食塩を加えればよいか。', '50g', '40g', '60g', '80g', '100g', '25g', '食塩は40g、水は360gで変わらない。20％の水よう液では水が80％なので全体は360÷0.8＝450g。加える食塩は450－400＝50g。', 1, 1),
('chikyu_lv4_058', 4, 'chikyu', '20℃の水200gに食塩72gをとかした飽和水よう液がある。この水を50g蒸発させて20℃にもどすと、何gの食塩の結晶が出る？（20℃の水100gに食塩は36gまでとける）', '18g', '36g', '9g', '50g', '72g', '24g', '蒸発した水50gにとけていた食塩が出る。36×50÷100＝18g。', 1, 1),
('chikyu_lv4_059', 4, 'chikyu', '塩酸10mLと水酸化ナトリウム水よう液15mLがちょうど中和した。同じ濃さの塩酸40mLをちょうど中和するには、水酸化ナトリウム水よう液は何mL必要？', '60mL', '27mL', '40mL', '45mL', '50mL', '80mL', '塩酸と水酸化ナトリウム水よう液は体積が10：15＝2：3でちょうど中和する。40mL×3/2＝60mL。', 1, 1),
('chikyu_lv4_060', 4, 'chikyu', '塩酸10mLと水酸化ナトリウム水よう液15mLがちょうど中和する。同じ濃さの塩酸30mLに、水酸化ナトリウム水よう液を20mL混ぜてBTB液を加えると何色になる？', '黄色', '青色', '緑色', '赤色', 'むらさき色', '無色', '30mLの塩酸をちょうど中和するには45mL必要。20mLでは足りず、塩酸が残って酸性になるので黄色。', 1, 1),
('chikyu_lv4_061', 4, 'chikyu', '塩酸20mLと水酸化ナトリウム水よう液30mLをちょうど中和するように混ぜ、水を蒸発させると、あとに残る白い固体は？', '食塩', '水酸化ナトリウム', '塩化水素', '炭酸ナトリウム', '石灰石', '何も残らない', '塩酸（塩化水素）と水酸化ナトリウムが反応すると、食塩（塩化ナトリウム）と水ができる。食塩は蒸発しないので残る。', 0, 1),
('chikyu_lv4_062', 4, 'chikyu', '一定量の塩酸に水酸化ナトリウム水よう液を少しずつ加えて温度をはかる。温度がもっとも高くなるのは、いつ？', 'ちょうど中和したとき', '加え始めたとき', '塩酸が多く残っているとき', '水酸化ナトリウムを加えすぎたとき', '中和の前後で変わらない', '中和するまえに一度下がるとき', '中和は熱が出る反応。ちょうど中和した点でいちばん多く熱が出て、温度が最高になる。', 0, 1),
('chikyu_lv4_063', 4, 'chikyu', 'アルミニウムの板は、塩酸と水酸化ナトリウム水よう液のどちらにとける？', 'どちらにもとける', '塩酸だけにとける', '水酸化ナトリウム水よう液だけにとける', 'どちらにもとけない', '水にだけとける', '食塩水にだけとける', 'アルミニウムは酸にもアルカリにも反応して水素を出してとける。鉄は塩酸にはとけるが、水酸化ナトリウム水よう液にはとけない。', 0, 1),
('chikyu_lv4_064', 4, 'chikyu', 'オキシドール（過酸化水素水）に二酸化マンガンを加えて酸素を発生させる。二酸化マンガンのはたらきはどれ？', '自分は変化せず、反応をはやめる', '酸素の材料になる', '反応のあと水にとけてなくなる', '酸素を水にとかす', '反応を止める', '酸素を重くする', '二酸化マンガンは触媒で、反応の前後でそれ自身は変化しない。酸素のもとは過酸化水素水。', 0, 1),
('chikyu_lv4_065', 4, 'chikyu', '石灰水に二酸化炭素を通すと白くにごる。さらに二酸化炭素を通しつづけると、どうなる？', 'うすくなって、ほぼ透明にもどる', 'さらに白くこくなる', '赤色に変わる', '青色に変わる', '変化しない', '気体が出て爆発する', '炭酸カルシウムが二酸化炭素と水と反応して、水にとける物質（炭酸水素カルシウム）に変わるため。', 0, 1),
('chikyu_lv4_066', 4, 'chikyu', '水素が発生する薬品の組み合わせはどれ？', '亜鉛とうすい塩酸', '銅とうすい塩酸', '石灰石とうすい塩酸', '二酸化マンガンとオキシドール', '塩化アンモニウムと水酸化カルシウム', '食塩と水', '亜鉛・鉄・アルミニウムなどの金属に塩酸をかけると水素が出る。銅は塩酸と反応しない。', 0, 1),
('chikyu_lv4_067', 4, 'chikyu', 'アンモニアを入れた丸底フラスコに少量の水を入れると、水が噴水のようにふき上がる。その理由は？', '水にとけて中の気圧が下がるから', '水にとけにくく気圧が上がるから', '水が熱で蒸発するから', 'アンモニアが水と反応して火を出すから', 'フラスコがあたためられるから', 'アンモニアが水より軽いから', 'アンモニアは水に非常によくとけるため、フラスコ内の気圧が下がり、外の水が吸い上げられる。', 0, 1),
('chikyu_lv4_068', 4, 'chikyu', 'アルミニウム0.1gを塩酸に入れると水素が130mL出る。塩酸40mLでは最大260mLの水素しか出ない（それ以上は塩酸が足りない）。アルミニウム0.5gを入れたとき、出る水素は？', '260mL', '650mL', '130mL', '390mL', '520mL', '325mL', '0.5gなら650mL出るはずだが、塩酸40mLで出せるのは最大260mL。アルミニウムが残る。', 1, 1),
('chikyu_lv4_069', 4, 'chikyu', '水素と酸素は、体積の比2：1で反応して水になる。水素40mLと酸素40mLを混ぜて点火し、反応が終わって室温にもどしたとき、残る気体は？', '酸素20mL', '水素20mL', '酸素40mL', '酸素10mL', '水素40mL', '酸素60mL', '水素40mLは酸素20mLと反応する。酸素は40－20＝20mL余る。できた水は液体なので、体積に数えない。', 1, 1),
('chikyu_lv4_070', 4, 'chikyu', '銅4gを十分に加熱すると、酸化銅5gになる。銅12gを十分に加熱すると、酸化銅は何gできる？', '15g', '10g', '13g', '16g', '20g', '60g', '銅と結びつく酸素は4gの銅で1g。銅12gなら酸素は3gで、12＋3＝15g。', 1, 1),
('chikyu_lv4_071', 4, 'chikyu', '銅4gが酸素1gと結びついて酸化銅5gになる。銅10gを加熱したところ12gになった。まだ酸化していない銅は何g残っている？', '2g', '4g', '8g', '1g', '0g', '6g', '増えた2gが結びついた酸素。酸素2gと結びつく銅は2×4＝8gなので、残りは10－8＝2g。', 1, 1),
('chikyu_lv4_072', 4, 'chikyu', 'マグネシウム3gは酸素2gと結びついて酸化マグネシウムになる。マグネシウム9gを燃やすとき、必要な酸素は何g？', '6g', '2g', '3g', '4.5g', '9g', '12g', 'マグネシウムと酸素の重さの比は3：2。9gなら酸素は9÷3×2＝6g。', 1, 1),
('chikyu_lv4_073', 4, 'chikyu', '体積50cm³、重さ135gの金属の密度（1cm³あたりの重さ）は何g/cm³？', '2.7g/cm³', '0.37g/cm³', '6.75g/cm³', '1.35g/cm³', '20g/cm³', '85g/cm³', '密度＝重さ÷体積＝135÷50＝2.7g/cm³。アルミニウムの密度は約2.7g/cm³。', 1, 1),
('chikyu_lv4_074', 4, 'chikyu', '密度0.9g/cm³の氷が水（1g/cm³）に浮いているとき、氷の体積のうち水面の上に出ているのは何％？', '10％', '90％', '1％', '50％', '19％', '9％', '浮いているときは、水中にある体積の割合が密度の比（0.9÷1）に等しい。水面上は1－0.9＝0.1で10％。', 1, 1),
('chikyu_lv4_075', 4, 'chikyu', '食塩を水にとかした食塩水を熱してふっとうさせたとき、ふっとうする温度（沸点）は純粋な水と比べてどうなる？', '100℃より少し高くなる', '100℃より少し低くなる', '100℃のまま変わらない', '0℃近くになる', 'ふっとうしなくなる', '90℃になる', '水に物質がとけていると沸点は高くなり、凝固点（こおる温度）は低くなる。', 0, 1),
('chikyu_lv4_076', 4, 'chikyu', '水1gの温度を1℃上げるのに必要な熱量を1calとする。水200gを20℃から60℃にするには、何calの熱が必要？', '8000cal', '800cal', '1600cal', '4000cal', '12000cal', '16000cal', '熱量＝水の重さ×上がった温度＝200×(60－20)＝8000cal。', 1, 1),
('chikyu_lv4_077', 4, 'chikyu', '20℃の水100gと50℃の水200gを混ぜると、全体の温度は何℃になる？（熱は外に逃げない）', '40℃', '35℃', '30℃', '45℃', '43℃', '38℃', '(100×20＋200×50)÷(100＋200)＝12000÷300＝40℃。重さがちがうので、平均の35℃にはならない。', 1, 1),
('chikyu_lv4_078', 4, 'chikyu', '0℃の氷1gを0℃の水にするには80calの熱が必要。0℃の氷50gをすべて0℃の水にするには、何calの熱が必要？', '4000cal', '80cal', '500cal', '2500cal', '5000cal', '8000cal', '氷がとけるあいだは温度が上がらず、熱はとけることに使われる。80×50＝4000cal。', 1, 1),
('chikyu_lv4_079', 4, 'chikyu', '長さ100cm、重さ200gの一様な棒の左はしから20cmの点を支点にして、棒の左はしにおもりをつるしたら、棒が水平につりあった。おもりは何g？', '300g', '100g', '150g', '200g', '400g', '500g', '棒の重さは真ん中（50cmの点）にかかる。支点から30cm。200×30＝おもり×20より、おもり＝300g。', 1, 1),
('chikyu_lv4_080', 4, 'chikyu', '重さの無視できる棒の支点から左30cmに40g、右20cmに20g、右40cmにあるおもりをつるして水平につりあった。右40cmのおもりは何g？', '20g', '10g', '30g', '40g', '60g', '15g', '左回り＝40×30＝1200。右回りは20×20＋□×40＝1200より、□＝20g。', 1, 1),
('chikyu_lv4_081', 4, 'chikyu', '半径20cmの輪と半径5cmの軸がいっしょに回る輪軸がある。軸につるした80gの物をつりあわせるには、輪にかけたひもに何gの力が必要？', '20g', '320g', '80g', '40g', '60g', '10g', '輪軸は（力×半径）が輪と軸でつりあう。80×5＝□×20より、□＝20g。', 1, 1),
('chikyu_lv4_082', 4, 'chikyu', '120gの物体を動滑車でつり下げる。物体と動滑車をささえているひもが4本のとき、ひもを引く力は何g？（滑車の重さは考えない）', '30g', '15g', '40g', '60g', '120g', '480g', 'ひも4本で重さを分けてささえるので、1本あたり120÷4＝30g。', 1, 1),
('chikyu_lv4_083', 4, 'chikyu', 'まさつのないなめらかな斜面（長さ4m、高さ1m）で、100gの台車を斜面にそって引き上げる。必要な力は何g？', '25g', '4g', '50g', '75g', '100g', '400g', '仕事の原理から、力×4m＝100g×1m。力は100×1÷4＝25g。', 1, 1),
('chikyu_lv4_084', 4, 'chikyu', '10gのおもりをつるすと2cmのびるばねが2本ある。この2本を直列につないで、60gのおもりをつるすと、のびは全部で何cm？', '24cm', '6cm', '12cm', '3cm', '48cm', '120cm', '直列では、それぞれのばねに60gがかかる。1本は12cmのびるので、2本で24cm。', 1, 1),
('chikyu_lv4_085', 4, 'chikyu', '10gのおもりをつるすと2cmのびるばねが2本ある。この2本を並列につないで、60gのおもりをつるすと、のびは何cm？', '6cm', '12cm', '24cm', '3cm', '2cm', '1.5cm', '並列では、1本に60÷2＝30gずつかかる。10gで2cmなので30gでは6cmのびる。', 1, 1),
('chikyu_lv4_086', 4, 'chikyu', 'ある物体をばねばかりでつるすと、空気中で120g、水中で70gを示した。この物体の体積は何cm³？（水1cm³の重さは1g）', '50cm³', '70cm³', '120cm³', '190cm³', '25cm³', '100cm³', '水中で軽くなった120－70＝50gが浮力。浮力は押しのけた水の重さなので、水50g＝50cm³。', 1, 1),
('chikyu_lv4_087', 4, 'chikyu', '重さ600gの直方体を、面積30cm²の面を下にして水平な台にのせた。台がうける圧力は1cm²あたり何g？', '20g/cm²', '0.05g/cm²', '10g/cm²', '570g/cm²', '600g/cm²', '18000g/cm²', '圧力＝力÷面積＝600÷30＝20g/cm²。面積が小さいほど圧力は大きくなる。', 1, 1),
('chikyu_lv4_088', 4, 'chikyu', 'ある電熱線に3Vの電圧をかけると0.5Aの電流が流れる。同じ電熱線2本を直列につないで3Vの電源につなぐと、電源から流れる電流は何A？', '0.25A', '0.125A', '0.5A', '0.75A', '1.0A', '1.5A', '直列にすると電流の通りにくさが2倍になるので、電流は半分の0.25A。', 1, 1),
('chikyu_lv4_089', 4, 'chikyu', 'ある電熱線に3Vの電圧をかけると0.5Aの電流が流れる。同じ電熱線2本を並列につないで3Vの電源につなぐと、電源から流れる電流は何A？', '1.0A', '0.25A', '0.5A', '0.75A', '1.5A', '2.0A', '並列では、どちらの電熱線にも3Vがかかり、0.5Aずつ流れる。電源から出る電流は合計の1.0A。', 1, 1),
('chikyu_lv4_090', 4, 'chikyu', '電熱線にかける電圧を2倍にすると、同じ時間に出る熱の量は何倍になる？', '4倍', '2倍', '8倍', '半分', '4分の1', '変わらない', '電圧が2倍になると電流も2倍。熱量は電圧×電流に比例するので、2×2＝4倍になる。', 0, 1),
('chikyu_lv4_091', 4, 'chikyu', '電磁石の引きつける力は巻き数に比例するとする。100回巻きの電磁石でクリップが4個つくとき、同じ電流で300回巻きにするとクリップは何個つく？', '12個', '8個', '6個', '16個', '36個', '24個', '巻き数が3倍になるので、引きつける力も3倍。4×3＝12個。', 1, 1),
('chikyu_lv4_092', 4, 'chikyu', '同じ豆電球AとBを並列にして乾電池につないだ。Aをソケットからはずすと、Bの明るさはどうなる？', '変わらない', '明るくなる', '暗くなる', '消える', '点滅する', 'Aと同じ色になる', '並列では、それぞれの豆電球に電池の電圧がかかる。片方をはずしてももう片方は影響を受けない。', 0, 1),
('chikyu_lv4_093', 4, 'chikyu', 'コイルに磁石を近づけたり遠ざけたりすると、コイルに電流が流れる。この現象を何という？', '電磁誘導', '電気分解', '静電気', '磁化', '電磁石', '放電', '磁石の動きでコイルに電流が生まれる現象を電磁誘導という。発電機の原理になっている。', 0, 1),
('chikyu_lv4_094', 4, 'chikyu', '身長160cmの人が、かべにかけた鏡で自分の全身をうつして見るには、鏡の縦の長さは最低何cm必要？（鏡からの距離は関係ない）', '80cm', '160cm', '40cm', '120cm', '100cm', '53cm', '鏡にうつる像は、頭からつま先までの高さの半分の長さの鏡があれば見える。160÷2＝80cm。', 0, 1),
('chikyu_lv4_095', 4, 'chikyu', '山に向かって大声を出すと、4秒後に山びこが聞こえた。音の速さを秒速340mとすると、山までの距離は何m？', '680m', '340m', '1360m', '85m', '170m', '2720m', '4秒は行きと帰りの往復の時間。山までの片道は2秒で、340×2＝680m。', 1, 1),
('chikyu_lv4_096', 4, 'chikyu', '焦点距離10cmの凸レンズの前方15cmの位置に物体を置いた。スクリーンにはっきり像ができるのは、レンズの後方何cmの位置？', '30cm', '6cm', '15cm', '20cm', '25cm', '5cm', 'レンズの式 1/物体の距離＋1/像の距離＝1/焦点距離より、1/15＋1/□＝1/10。□＝30cm。', 1, 1),
('chikyu_lv4_097', 4, 'chikyu', '焦点距離10cmの凸レンズの前方20cmに物体を置くと、スクリーンにできる像はどうなる？', '同じ大きさで上下左右が逆', '2倍の大きさで上下左右が逆', '半分の大きさで上下左右が逆', '同じ大きさで同じ向き', '2倍の大きさで同じ向き', '像はできない', '焦点距離の2倍の位置に置くと、後方の焦点距離の2倍の位置に、同じ大きさの上下左右が逆の実像ができる。', 0, 1),
('chikyu_lv4_098', 4, 'chikyu', '光は1秒間に約30万km進む。地球から月までの距離を約38万kmとすると、光が月から地球に届くまでの時間は約何秒？', '約1.3秒', '約0.3秒', '約3秒', '約8秒', '約20秒', '約1分', '時間＝距離÷速さ＝38万÷30万＝約1.3秒。', 1, 1),
('chikyu_lv4_099', 4, 'chikyu', 'ふりこの周期はふりこの長さの平方根に比例する。長さ25cmのふりこの周期が1秒のとき、長さ225cmのふりこの周期は何秒？', '3秒', '9秒', '6秒', '2秒', '4.5秒', '1.5秒', '225÷25＝9倍の長さなので、周期は√9＝3倍。1×3＝3秒。9倍にはならない。', 1, 1),
('chikyu_lv4_100', 4, 'chikyu', 'あるふりこが10往復するのに20秒かかった。このふりこの長さを4分の1にすると、10往復するのに何秒かかる？', '10秒', '5秒', '40秒', '15秒', '20秒', '2.5秒', '長さが4分の1なら周期は半分（√(1/4)＝1/2）。10往復も半分の10秒になる。', 1, 1)
