('eigo_lv4_073', 4, 'eigo', '「I was born ( ) Nagoya.」の ( ) に入る語は？', 'in', 'on', 'to', 'by', 'of', 'from', '都市や国の前には in を使います。', 0, 1),
('eigo_lv4_074', 4, 'eigo', '「A girl ( ) long hair is my sister.」の ( ) に入る語は？', 'with', 'of', 'on', 'at', 'in', 'for', 'with ～ は「～を持った」。特ちょうを表します。', 0, 1),
('eigo_lv4_075', 4, 'eigo', '「I''m proud ( ) my brother.」の ( ) に入る語は？', 'of', 'at', 'in', 'on', 'to', 'with', 'be proud of ～ で「～をほこりに思う」です。', 0, 1),
('eigo_lv4_076', 4, 'eigo', '「2:45」を英語で言うとき、合うのはどれ？', 'a quarter to three', 'a quarter past two', 'a quarter to two', 'half past two', 'half past three', 'a quarter to four', 'quarter は4分の1（15分）。to は「～前」なので、3時15分前＝2:45 です。', 0, 1),
('eigo_lv4_077', 4, 'eigo', '「It''s half past seven.」は何時のこと？', '7時30分', '6時30分', '7時15分', '7時45分', '8時30分', '8時', 'half は「半分」、past は「すぎ」。7時半です。', 0, 1),
('eigo_lv4_078', 4, 'eigo', '「It''s ten to eight.」は何時のこと？', '7時50分', '8時10分', '7時10分', '8時50分', '10時8分', '8時', 'to は「～前」。8時10分前なので7時50分です。', 0, 1),
('eigo_lv4_079', 4, 'eigo', '「April 1st」の読み方として正しいものはどれ？', 'April first', 'April one', 'April oneth', 'April firstly', 'April onest', 'April one-th', '日付は序数で読みます。1日は first です。', 0, 1),
('eigo_lv4_080', 4, 'eigo', '「5月3日」の読み方として正しいものはどれ？', 'May third', 'May three', 'May the three', 'May threeth', 'May thirdly', 'May third day', '日付は序数で読むので、3日は third です。', 0, 1),
('eigo_lv4_081', 4, 'eigo', '今日が水曜日のとき、yesterday は何曜日？', 'Tuesday', 'Monday', 'Thursday', 'Friday', 'Sunday', 'Saturday', 'yesterday（昨日）は今日の前の日。水曜日の前は火曜日です。', 0, 1),
('eigo_lv4_082', 4, 'eigo', '今日が金曜日のとき、the day after tomorrow は何曜日？', 'Sunday', 'Saturday', 'Monday', 'Thursday', 'Wednesday', 'Tuesday', 'the day after tomorrow は「あさって」。金曜日の2日後は日曜日です。', 0, 1),
('eigo_lv4_083', 4, 'eigo', '「This bag is ( ) than that one.」の ( ) に入る語は？', 'better', 'gooder', 'more good', 'best', 'well', 'most good', 'good の比較級は better。gooder とは言いません。', 0, 1),
('eigo_lv4_084', 4, 'eigo', '「This is the ( ) movie I have ever seen.」の ( ) に入る語は？', 'most interesting', 'more interesting', 'interestinger', 'interestingest', 'much interesting', 'interesting', '長い形容詞は most をつけて最上級にします。', 0, 1),
('eigo_lv4_085', 4, 'eigo', '「Mt. Fuji is the ( ) mountain in Japan.」の ( ) に入る語は？', 'highest', 'higher', 'high', 'more high', 'most high', 'highly', 'the のあとに最上級。high は -est をつけて highest です。', 0, 1),
('eigo_lv4_086', 4, 'eigo', '「My bag is ( ) than yours.」の ( ) に入る語は？', 'heavier', 'heavyer', 'more heavy', 'heavy', 'heaviest', 'most heavy', 'heavy は y を i に変えて -er。heavier です。', 0, 1),
('eigo_lv4_087', 4, 'eigo', '「English is ( ) difficult than math for me.」の ( ) に入る語は？', 'more', 'most', 'much', 'very', 'too', 'so', 'difficult のような長い形容詞は more ～ than で比べます。', 0, 1),
('eigo_lv4_088', 4, 'eigo', '「This dog is ( ) than that one.」の ( ) に入る語は？', 'bigger', 'biger', 'more big', 'biggest', 'bigest', 'much big', 'big は最後の g を重ねて -er。bigger です。', 0, 1),
('eigo_lv4_089', 4, 'eigo', '「I like soccer ( ) than baseball.」の ( ) に入る語は？', 'better', 'good', 'best', 'well', 'more well', 'gooder', 'like A better than B で「B より A が好き」です。', 0, 1),
('eigo_lv4_090', 4, 'eigo', '「She sings the ( ) of all the girls.」の ( ) に入る語は？', 'best', 'better', 'good', 'well', 'most well', 'goodest', 'well の最上級は best。the best of ～ で「～の中でいちばん」。', 0, 1),
('eigo_lv4_091', 4, 'eigo', '「Mike is as ( ) as Tom.」の ( ) に入る語は？', 'old', 'older', 'oldest', 'more old', 'the old', 'oldly', 'as ～ as の間には、形容詞をもとの形（原級）のまま入れます。older のような比較級にはしません。', 0, 1),
('eigo_lv4_092', 4, 'eigo', '「Nobody in my family is taller than my father.」の意味は？', '父が家族でいちばん背が高い', '父が家族でいちばん背が低い', '父は家族で2番目に高い', '家族はみな父より背が高い', '父より背の高い人がいる', '父はいちばん年上だ', '「父より背が高い人はいない」＝父がいちばん背が高い、という意味です。', 0, 1),
('eigo_lv4_093', 4, 'eigo', '「good - better - ( )」の ( ) に入る語は？', 'best', 'goodest', 'bestest', 'most good', 'well', 'gooder', 'good の変化は good - better - best。不規則に変わります。', 0, 1),
('eigo_lv4_094', 4, 'eigo', '「many」の比較級はどれ？', 'more', 'manier', 'manyer', 'mucher', 'most', 'moreer', 'many と much の比較級はどちらも more。最上級は most です。', 0, 1),
('eigo_lv4_095', 4, 'eigo', '「bad - worse - ( )」の ( ) に入る語は？', 'worst', 'baddest', 'worsest', 'most bad', 'badest', 'worse', 'bad の変化は bad - worse - worst。不規則に変わります。', 0, 1),
('eigo_lv4_096', 4, 'eigo', '「Ken ( ) to school by bike every day.」の ( ) に入る語は？', 'goes', 'go', 'going', 'gone', 'gos', 'is go', '主語が Ken（3人称・単数）で現在の習慣なので、go に es がついて goes。', 0, 1),
('eigo_lv4_097', 4, 'eigo', '「There ( ) two books on the desk.」の ( ) に入る語は？', 'are', 'is', 'be', 'am', 'has', 'have', 'There is/are のあとの名詞が複数（two books）なので are を使います。', 0, 1),
('eigo_lv4_098', 4, 'eigo', '「I''m going to ( ) my grandmother tomorrow.」の ( ) に入る語は？', 'visit', 'visiting', 'visited', 'visits', 'to visit', 'am visit', 'be going to のあとは動詞の原形。visit です。', 0, 1),
('eigo_lv4_099', 4, 'eigo', '「Mika ( ) have breakfast this morning because she was late.」の ( ) に入る語は？', 'didn''t', 'don''t', 'doesn''t', 'isn''t', 'wasn''t', 'hasn''t', 'this morning の出来事で、was late と過去の話。過去の否定は didn''t です。', 0, 1),
('eigo_lv4_100', 4, 'eigo', '「I haven''t ( ) my homework yet.」の ( ) に入る語は？', 'finished', 'finish', 'finishing', 'finishes', 'to finish', 'am finish', '現在完了 have + 過去分詞。finish の過去分詞は finished です。', 0, 1)
INSERT INTO battle_questions
  (src_key, level, category, question_text, answer, wrong1, wrong2, wrong3, wrong4, wrong5, explanation, needs_calc, is_active)
VALUES
('ikimono_lv4_001', 4, 'ikimono', '光合成でつくられたデンプンは水にとけにくい。そのため、夜のあいだに葉から運び出されるときは、何に変わっている？', '糖', '脂肪', 'タンパク質', 'ビタミン', '無機養分', '二酸化炭素', 'デンプンは水にとけやすい糖に変わり、師管を通って、根や果実などに運ばれる。', 0, 1),
('ikimono_lv4_002', 4, 'ikimono', '葉にデンプンができたかをヨウ素液で調べるとき、先にあたためたエタノールに葉を入れるのは、何のため？', '葉の緑色をぬくため', 'デンプンをふやすため', '葉を殺菌するため', '二酸化炭素を出すため', '葉をぬらすため', '酸素をふやすため', '葉の緑色が残っていると、ヨウ素液による青むらさき色の変化が見えにくい。そこでエタノールで緑色をぬく。', 0, 1),
('ikimono_lv4_003', 4, 'ikimono', 'ふ入りの葉（緑の部分と白い部分がある葉）に、日光をよく当てたあと、ヨウ素液につけると、青むらさき色になるのは？', '緑の部分だけ', '白い部分だけ', '葉全体', 'ふちだけ', '葉脈だけ', 'どこも変わらない', '白い部分には葉緑体がなく、光合成ができないのでデンプンができない。', 0, 1),
('ikimono_lv4_004', 4, 'ikimono', '植物が、呼吸をおこなっているのは、いつ？', '昼も夜もつねに', '昼だけ', '夜だけ', '光が弱いときだけ', '日光が当たるときだけ', '花がさくときだけ', '呼吸は生きているかぎり一日中おこなわれる。昼は光合成もしているので、見かけ上の気体の出入りが逆になる。', 0, 1),
('ikimono_lv4_005', 4, 'ikimono', '息をふきこんで黄色にしたBTB液に、オオカナダモを入れ、明るい所に置いておくと、液の色はどうなる？', '緑や青に近づく', '黄色のまま', '赤色になる', '無色になる', '黄色がこくなる', '黒くなる', '光合成で二酸化炭素が使われて、液が酸性からだんだん中性・アルカリ性にもどり、緑や青になる。', 0, 1),
('ikimono_lv4_006', 4, 'ikimono', '同じ大きさの枝A〜Dを水の入った試験管にさし、Aはそのまま、Bは葉の表だけ、Cは葉の裏だけ、Dは葉の表も裏もワセリンをぬった。水の減少量はA=10、B=8、C=3、D=1（mL）。葉の裏から出ていった水は何mL？', '7mL', '2mL', '3mL', '8mL', '9mL', '1mL', 'A−C=10−3=7mL。Cは裏がふさがれて表と茎だけから蒸散しているので、AとCの差が裏からの量。', 1, 1),
('ikimono_lv4_007', 4, 'ikimono', '蒸散がもっとも盛んになるのは、次のうちどの条件のとき？', '高温・強風・低湿度', '高温・無風・高湿度', '低温・強風・低湿度', '高温・強風・高湿度', '低温・無風・高湿度', '低温・強風・高湿度', '気温が高く、風が強く、空気がかわいているほど、水蒸気が気孔から出ていきやすい。', 0, 1),
('ikimono_lv4_008', 4, 'ikimono', '気孔をつくっている、2つの三日月形の細胞を何という？', '孔辺細胞', '表皮細胞', 'さく状組織', '海綿状組織', '師管', '道管', '2つの孔辺細胞がふくらんだりしぼんだりして、気孔をひらいたり閉じたりする。', 0, 1),
('ikimono_lv4_009', 4, 'ikimono', '葉脈の中を通る道管と師管で、葉の表側に近いほうにあるのは？', '道管', '師管', '孔辺細胞', '表皮', 'さく状組織', '海綿状組織', '葉脈の断面では、表側に道管、裏側に師管がならんでいる。', 0, 1),
('ikimono_lv4_010', 4, 'ikimono', '双子葉植物の茎で、道管と師管のあいだにあり、茎を太くする細胞の層を何という？', '形成層', '表皮', '髄', '皮層', '孔辺細胞', '根冠', '形成層の細胞がさかんに分裂して、茎が太くなる。単子葉植物には形成層がない。', 0, 1),
('ikimono_lv4_011', 4, 'ikimono', '次のうち、種子に胚乳がある（有胚乳種子）のはどれ？', 'イネ', 'ダイズ', 'インゲンマメ', 'エンドウ', 'クリ', 'ヘチマ', 'イネは胚乳に養分をためる。ほかの5つは、子葉に養分をためる無胚乳種子。', 0, 1),
('ikimono_lv4_012', 4, 'ikimono', '種子の中の胚のうち、将来、根になる部分はどれ？', '幼根', '幼芽', '子葉', '胚乳', '種皮', 'へそ', '胚は子葉・幼芽・胚軸・幼根でできていて、発芽すると幼根が根になる。', 0, 1),
('ikimono_lv4_013', 4, 'ikimono', 'アサガオは、昼が短く夜が長くなると、花芽をつくる。このような植物を何という？', '短日植物', '長日植物', '中性植物', '陽性植物', '陰性植物', '一年草', '正確には、夜の長さが一定以上になると花芽をつくる。アサガオやコスモス、キクなどが短日植物。', 0, 1),
('ikimono_lv4_014', 4, 'ikimono', '光合成がおこなわれる、植物の細胞の中の緑色の粒を何という？', '葉緑体', '核', '液胞', '細胞壁', 'ミトコンドリア', '細胞膜', '葉緑体の中の葉緑素が光を受けとって、光合成をおこなう。', 0, 1),
('ikimono_lv4_015', 4, 'ikimono', '光を十分に強くしても、これ以上、光合成の速さが上がらなくなった。次に光合成が速くなる可能性があるのは？', '二酸化炭素をふやす', '光をさらに強める', '酸素をふやす', '葉をぬらす', '土の温度を下げる', '気孔をふさぐ', '光が十分なときは、二酸化炭素の量や温度が光合成の速さを決める。', 0, 1),
('ikimono_lv4_016', 4, 'ikimono', '暗い所で、植物が毎時2mgの二酸化炭素を出した。明るい所では、毎時6mgの二酸化炭素を差し引きで吸収した。呼吸の量が一定なら、光合成で使われた二酸化炭素は毎時何mg？', '8mg', '4mg', '6mg', '2mg', '12mg', '3mg', '見かけの吸収量6mgに、呼吸で出た2mgを足した8mgが、実際に光合成で使った量。', 1, 1),
('ikimono_lv4_017', 4, 'ikimono', '暗い所で毎時2mg、明るい所で毎時6mg（差し引き）の二酸化炭素を出入りさせる植物がある。明るい時間12時間・暗い時間12時間の1日で、差し引き何mgの二酸化炭素をとり入れる？', '48mg', '72mg', '96mg', '24mg', '36mg', '8mg', '明るい時間に6×12=72mg吸収し、暗い時間に2×12=24mg出す。差し引き72−24=48mg。', 1, 1),
('ikimono_lv4_018', 4, 'ikimono', 'オオカナダモを明るい所に置いたとき、葉から出てくる泡は、おもに何？', '酸素', '二酸化炭素', '水素', 'ちっ素', '水蒸気', 'アンモニア', '光合成で酸素ができて、泡になって出てくる。', 0, 1),
('ikimono_lv4_019', 4, 'ikimono', '根の先たんの近くにあって、細胞分裂がさかんで根を伸ばす部分を何という？', '成長点', '根冠', '根毛', '主根', '側根', '形成層', '根の先の根冠の内側に成長点があり、ここで細胞が分裂して根が伸びる。', 0, 1),
('ikimono_lv4_020', 4, 'ikimono', 'トウモロコシの「ひげ」は、花のどの部分にあたる？', 'めしべ', 'おしべ', '花びら', '根', '葉脈', 'がく', 'ひげの1本が1つぶのめしべで、花粉がつくと、つけ根の部分が実（つぶ）になる。', 0, 1),
('ikimono_lv4_021', 4, 'ikimono', 'イチゴの、赤くて甘く食べる部分は、花のどの部分が育ったもの？', '花托', '子房', '胚珠', 'がく', '種子', 'おしべ', '赤い部分は花托が育ったもの。表面のつぶつぶが、本当の果実（種子のように見える）。', 0, 1),
('ikimono_lv4_022', 4, 'ikimono', 'シダ植物の胞子が発芽して育つ、小さなハート形の体を何という？', '前葉体', '胞子のう', '胚珠', '花粉管', '根茎', 'ツクシ', '前葉体の上で精子と卵が受精し、そこから、私たちの見るシダの葉の部分が育つ。', 0, 1),
('ikimono_lv4_023', 4, 'ikimono', '葉が緑色に見えるのは、葉緑体が、どんなはたらきをしているため？', '緑の光を吸収しにくい', '緑の光をよく吸収する', '赤い光をよく反射する', '青い光を反射する', 'あらゆる光を吸収', '光は吸収しない', '葉緑素は赤や青の光をよく吸収し、緑の光はあまり吸収せずにはね返す。だから緑色に見える。', 0, 1),
('ikimono_lv4_024', 4, 'ikimono', '秋に木が葉を落とすとき、葉のつけねにできる、水や養分の通り道をふさぐ層を何という？', '離層', '気孔', '年輪', '形成層', '根冠', '師管', '離層ができると、葉が枝から切りはなされ、落葉する。', 0, 1),
('ikimono_lv4_025', 4, 'ikimono', 'サボテンのトゲは、植物のどの部分が変化したもの？', '葉', '根', 'くき', '花', '実', '種子', 'サボテンのトゲは葉が変化したもの。くきで水をたくわえ、蒸散を防いでいる。', 0, 1),
('ikimono_lv4_026', 4, 'ikimono', '胃液にふくまれ、タンパク質を分解する消化酵素はどれ？', 'ペプシン', 'アミラーゼ', 'リパーゼ', 'マルターゼ', 'セルラーゼ', 'カタラーゼ', 'ペプシンは、塩酸をふくむ酸性の胃液ではたらき、タンパク質を分解する。', 0, 1),
('ikimono_lv4_027', 4, 'ikimono', '脂肪を分解する消化酵素はどれ？', 'リパーゼ', 'ペプシン', 'アミラーゼ', 'マルターゼ', 'カタラーゼ', 'セルラーゼ', 'リパーゼは、おもにすい液にふくまれ、胆汁のはたらきで細かくなった脂肪を分解する。', 0, 1),
('ikimono_lv4_028', 4, 'ikimono', 'だ液・胃液・すい液・胆汁のうち、デンプン・タンパク質・脂肪のすべてを分解する酵素をふくむのはどれ？', 'すい液', 'だ液', '胃液', '胆汁', 'リンパ液', '血しょう', 'すい液は、デンプン・タンパク質・脂肪をそれぞれ分解する3種類の酵素をふくむ。', 0, 1),
('ikimono_lv4_029', 4, 'ikimono', 'タンパク質が消化されて、最終的に小腸で吸収される形になったものは何？', 'アミノ酸', 'ブドウ糖', '脂肪酸', '麦芽糖', 'ペプトン', 'ビタミン', 'タンパク質はアミノ酸に分解される。ブドウ糖はデンプン、脂肪酸は脂肪の分解物。', 0, 1),
('ikimono_lv4_030', 4, 'ikimono', '小腸の柔毛で、脂肪の分解物（脂肪酸など）は、おもにどこに入って運ばれる？', 'リンパ管', '毛細血管', '道管', '気管', '輸尿管', '胆管', 'ブドウ糖とアミノ酸は柔毛の毛細血管に入るが、脂肪酸などはリンパ管に入る。', 0, 1),
('ikimono_lv4_031', 4, 'ikimono', '小腸で吸収された養分を運ぶ血液が、最初に流れこむ器官はどれ？', 'かん臓', '心臓', '肺', 'じん臓', '胃', 'すい臓', '小腸からの血液は、門脈という血管を通ってかん臓に入り、養分の貯蔵などがおこなわれる。', 0, 1),
